INSERT INTO cross_work_link_translations(link_id,locale,label,basis_note,status) VALUES
  ('4f94fa3d-b2eb-400b-87ac-534e42829938','zh-CN','理查·施特劳斯《莎乐美》','取材自马太福音 14 与马可福音 6 的叙事，经王尔德剧本转手，属现代接受而非经文设置。「莎乐美」之名不见于圣经，马可福音只作「希罗底的女儿」，该名出自约瑟夫《犹太古史》。','published'),
  ('4f94fa3d-b2eb-400b-87ac-534e42829938','en','R. Strauss, Salome','Drawn from Matthew 14 and Mark 6 by way of Wilde''s play: modern reception, not a setting of the text. The name Salome is not in the Bible — Mark says only "the daughter of Herodias"; the name comes from Josephus.','published')
