INSERT INTO cross_work_link_translations(link_id,locale,label,basis_note,status) VALUES
  ('2454e610-91b6-4b7b-8606-4a89829d851c','zh-CN','伯德《圣体颂》','十四世纪圣体文本，属拉丁礼传统的圣体崇敬，不是最后晚餐叙事的经文设置。伯德是伊丽莎白治下的天主教 recusant，此类作品为私下礼拜而写。','published'),
  ('2454e610-91b6-4b7b-8606-4a89829d851c','en','Byrd, Ave verum corpus','A fourteenth-century Eucharistic text belonging to Latin-rite devotion to the Body of Christ, not a setting of the supper narrative. Byrd was a Catholic recusant under Elizabeth I, writing such works for worship held in private.','published')
